def _split_polygon(poly, n, o):
    """Split a convex polygon by an exact plane, preserving only 2D cells."""
    ds = [dot(n, sub(p, o)) for p in poly]
    if min(ds) >= 0 or max(ds) <= 0:
        return [poly]
    sides = [[], []]
    for i, p in enumerate(poly):
        q = poly[(i + 1) % len(poly)]
        a = ds[i]
        b = ds[(i + 1) % len(poly)]
        if a >= 0:
            sides[0].append(p)
        if a <= 0:
            sides[1].append(p)
        if a * b < 0:
            x = add(p, mul(sub(q, p), a / (a - b)))
            sides[0].append(x)
            sides[1].append(x)
    return sides

