def _polyomino(rng, ncells, span=6):
    """随机生长的格子集合，边界是一条简单闭链（无洞、无角点相切）时返回 (格子集合, 边界多边形)，否则 None。
    边界按单位步长取点：每个格点都是顶点，直边中间的全是平直顶点（DDA 块边上的 T 形顶点就是这样）。"""
    cells = {(0, 0)}
    while len(cells) < ncells:
        i, j = rng.choice(sorted(cells))
        di, dj = rng.choice(((1, 0), (-1, 0), (0, 1), (0, -1)))
        if abs(i + di) <= span and abs(j + dj) <= span:
            cells.add((i + di, j + dj))
    nxt = {}
    for i, j in cells:
        for inside, a, b in (((i, j - 1), (i, j), (i + 1, j)), ((i + 1, j), (i + 1, j), (i + 1, j + 1)), ((i, j + 1), (i + 1, j + 1), (i, j + 1)), ((i - 1, j), (i, j + 1), (i, j))):
            if inside not in cells:
                if a in nxt:
                    return None
                nxt[a] = b
    start = min(nxt)
    ring, p = ([start], nxt[start])
    while p != start:
        ring.append(p)
        p = nxt[p]
    if len(ring) != len(nxt):
        return None
    return (cells, [(scalar_exact(x), scalar_exact(y)) for x, y in ring])

