def load_step_geometries(verts_csv: Path, *, dup_tol: float=1e-12) -> dict[int, StepGeometry]:
    by: dict[int, dict[int, list[tuple[int, tuple[float, float]]]]] = defaultdict(lambda: defaultdict(list))
    with Path(verts_csv).open(newline='', encoding='utf-8') as fh:
        for r in csv.DictReader(fh):
            by[int(r['step'])][int(r['block'])].append((int(r['vidx']), (float(r['x']), float(r['y']))))
    out: dict[int, StepGeometry] = {}
    for step, blocks in by.items():
        sg = StepGeometry(step=step, blocks={})
        for b, lst in blocks.items():
            lst.sort()
            vids, poly, alias = strip_duplicate_vertices([v for v, _ in lst], [p for _, p in lst], dup_tol, block=b)
            sg.alias.update(alias)
            ccw, flipped = ensure_ccw(poly)
            sg.blocks[b] = BlockGeom(b, ccw, list(reversed(vids)) if flipped else vids, flipped)
        out[step] = sg
    return out

def load_blocks(step: int=1) -> tuple[dict, dict[int, int]]:
    """从 verts.csv 重建多边形；剥离尾部回绕重复点与**任何**循环连续重复点（零长边，审查 C19），
    返回 alias（被剥 vidx -> 保留 vidx）。剥点规则与 readers.bdda_geom 共用同一个函数。"""
    with (FIX / 'bdda_debug_verts.csv').open(newline='', encoding='utf-8') as fh:
        rows = [r for r in csv.DictReader(fh) if int(r['step']) == step]
    by: dict[int, list[tuple[int, tuple[float, float]]]] = defaultdict(list)
    for r in rows:
        by[int(r['block'])].append((int(r['vidx']), (float(r['x']), float(r['y']))))
    blocks = {}
    alias: dict[int, int] = {}
    for b, lst in by.items():
        lst.sort()
        vids, poly, al = strip_duplicate_vertices([v for v, _ in lst], [p for _, p in lst], 1e-12, block=b)
        alias.update(al)
        ccw, flipped = ensure_ccw(poly)
        gmap = list(reversed(vids)) if flipped else vids
        blocks[b] = {'poly': ccw, 'vidx': gmap, 'flipped': flipped}
    return (blocks, alias)

def _clip_area(T, U):
    """独立 oracle ②：Sutherland–Hodgman 精确裁剪（凸 T 被凸 U 裁），返回交集面积（Fraction）。与 SAT 不同路。"""
    out = list(T)
    for i in range(3):
        a, b = (U[i], U[(i + 1) % 3])
        inp, out = (out, [])
        if not inp:
            break
        for j in range(len(inp)):
            p, q = (inp[j - 1], inp[j])
            sp, sq = (_fr_cross(a, b, p), _fr_cross(a, b, q))
            if sq >= 0:
                if sp < 0:
                    t = sp / (sp - sq)
                    out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
                out.append(q)
            elif sp >= 0:
                t = sp / (sp - sq)
                out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
    if len(out) < 3:
        return _Fr(0)
    return sum((_fr_cross((0, 0), out[i], out[(i + 1) % len(out)]) for i in range(len(out)))) / 2

