def _area_centroid(P):
    a = cx = cy = 0.0
    for i in range(len(P)):
        (x0, y0), (x1, y1) = (P[i], P[(i + 1) % len(P)])
        w = x0 * y1 - x1 * y0
        a += w
        cx += (x0 + x1) * w
        cy += (y0 + y1) * w
    a *= 0.5
    return (a, (cx / (6 * a), cy / (6 * a)))

